-- Club-Logo aus der Originaldatei: das Hochladen verkleinerte Logos bisher auf 160 Pixel, das wirkte auf dem Ladebildschirm verpixelt. Idempotent.
update public.league_state
set data = jsonb_set(data, '{logo}', to_jsonb('data:image/webp;base64,'::text)), client = 'club-logo', updated_at = now()
where id = 'main' and length(coalesce(data->>'logo', '')) < 10000;
